from pathlib import Path
from PIL import Image,ImageChops,ImageDraw
import json,math
ROOT=Path('/home/michael/Github/energy-plus-quest');R=ROOT/'docs/reviews/inventory-2026-10-22-finish';m=json.loads((R/'keeper-billboard-v5.json').read_text());region=m['source_crop_xyxy'];x0,y0,x1,y1=region
base=Image.open(R/'source-v3-clean.png').convert('RGBA').crop(region);raw=Image.open(R/'keeper-v5-native-render.png').convert('RGBA');assert raw.size==base.size
bounds=m['original_keeper_projected_bounds'];card=m['billboard_projected_bounds'];rect=[math.floor(min(bounds[0],card[0]))-x0-2,math.floor(min(bounds[1],card[1]))-y0-2,math.ceil(max(bounds[2],card[2]))-x0+2,math.ceil(max(bounds[3],card[3]))-y0+2]
mask=Image.new('L',base.size);ImageDraw.Draw(mask).rectangle(rect,fill=255);proof=Image.composite(raw,base,mask)
base.save(R/'keeper-v3-source-crop.png');proof.save(R/'keeper-v5-protected-proof.png');mask.save(R/'keeper-v5-context-protection-mask.png')
pair=Image.new('RGBA',(base.width*2+16,base.height),(255,255,255,255));pair.paste(base,(0,0));pair.paste(proof,(base.width+16,0));pair.save(R/'keeper-v3-v5-paired-proof.png');pair.resize((pair.width*3,pair.height*3)).save(R/'keeper-v3-v5-paired-proof-3x.png')
diff=ImageChops.difference(base.convert('RGB'),proof.convert('RGB'));rawdiff=ImageChops.difference(base.convert('RGB'),raw.convert('RGB'));outside=[i for i,a in enumerate(mask.get_flattened_data()) if a==0];d=list(diff.get_flattened_data());rd=list(rawdiff.get_flattened_data());changed=sum(any(d[i]) for i in outside);assert changed==0
rec={'status':'local comparison only; no production promotion','crop_source_full_dimensions':[1440,1000],'source_crop_xyxy':region,'output_crop_dimensions':list(base.size),'protected_context_policy':'Retain exact decoded v3 source context outside union of old evaluated keeper silhouette and new card bounds, with 2px margin. This is proof-only compositing, not editing the native sprite.','local_comparison_mask_xyxy':rect,'outside_mask_pixels_checked':len(outside),'outside_mask_changed_pixels':changed,'outside_mask_max_channel_difference':max(max(d[i]) for i in outside),'raw_rerender_outside_changed_pixels':sum(any(rd[i]) for i in outside),'raw_rerender_note':'Cycles crop denoising/sample changes alter unrelated pixels. Raw regional render retained and disclosed; context-protected proof copies exact v3 pixels outside the keeper region.','native_sprite_edited':False,'native_sprite_alpha_cutoff_shader':192/255,'card_fits_original_horizontal_envelope':card[0]>=bounds[0] and card[2]<=bounds[2],'card_matches_original_projected_top_and_bottom':card[1]==bounds[1] and card[3]==bounds[3]};(R/'keeper-v5-context-equality.json').write_text(json.dumps(rec,indent=2));print(json.dumps(rec,indent=2))
